    "hilos",
    "mcp",
    "chat",
    "agents"
  ],
  "userConfig": {
    "hilos_mcp_token": {
      "type": "string",
      "title": "hilos personal token",
      "description": "Paste the token shown once in hilos Settings → Connections.",
      "sensitive": true,
      "required": true
    }
  }
}
